import subprocess
import time
import sys

def main():
    print("Starting weather server...")
    weather_process = subprocess.Popen([sys.executable, "weather.py"])
    time.sleep(2)
    
    print("Starting client...")
    subprocess.run([sys.executable, "client.py"])
    
    weather_process.terminate()

if __name__ == "__main__":
    main()
